using CouponBook.Data;
using CouponBook.Data.Entities;
using Microsoft.EntityFrameworkCore;
namespace CouponBook.Business.Catalog;

public interface ICatalogService { Task<List<CityDto>> GetCitiesAsync(); Task<List<CategoryDto>> GetCategoriesAsync(); Task<List<BookListItemDto>> GetBooksAsync(int? cityId, int? categoryId, string? search = null); Task<BookDetailDto?> GetBookAsync(int id); }
public class CatalogService : ICatalogService
{
    private readonly AppDbContext _db; public CatalogService(AppDbContext db) => _db = db;
    private IQueryable<Book> Visible() => _db.Books.AsNoTracking().Where(b => b.Status == BookStatus.Published && b.SaleStartAt <= DateTime.UtcNow && b.SaleEndAt >= DateTime.UtcNow);
    public Task<List<CityDto>> GetCitiesAsync() => _db.Cities.AsNoTracking().Where(x => x.IsActive).OrderBy(x => x.NameEn).Select(x => new CityDto(x.Id, x.NameAr, x.NameEn)).ToListAsync();
    public Task<List<CategoryDto>> GetCategoriesAsync() => _db.Categories.AsNoTracking().OrderBy(x => x.NameEn).Select(x => new CategoryDto(x.Id, x.NameAr, x.NameEn, x.Icon)).ToListAsync();
    private IQueryable<Book> Filter(int? cityId, int? categoryId, string? search) { var q = Visible(); if (cityId != null) q = q.Where(x => x.CityId == cityId); if (categoryId != null) q = q.Where(x => x.Vouchers.Any(v => v.Provider.CategoryId == categoryId)); if (!string.IsNullOrWhiteSpace(search)) q = q.Where(x => x.Title.Contains(search) || x.Vouchers.Any(v => v.Title.Contains(search) || v.Provider.Name.Contains(search))); return q; }
    public async Task<List<BookListItemDto>> GetBooksAsync(int? cityId, int? categoryId, string? search = null) { var books = await Filter(cityId, categoryId, search).Include(x => x.City).Include(x => x.Vouchers).Select(b => new { b.Id, b.Title, b.CoverUrl, b.City, b.Price, b.Currency, b.ValidityDays, b.SaleEndAt, VoucherCount = b.Vouchers.Count, Total = b.Vouchers.Sum(v => v.FaceValue * v.UsageLimit), Quotas = b.Vouchers.Select(v => new { v.ProviderQuota, Sold = _db.PurchasedBooks.Count(pb => pb.BookId == b.Id && pb.Status != PurchasedBookStatus.Refunded) }) }).ToListAsync(); return books.Select(b => new BookListItemDto(b.Id, b.Title, b.CoverUrl, new CityDto(b.City.Id, b.City.NameAr, b.City.NameEn), b.Price, b.Currency, b.ValidityDays, b.SaleEndAt, b.VoucherCount, b.Total, b.Quotas.Count() == 0 ? 0 : b.Quotas.Min(q => Math.Max(0, q.ProviderQuota - q.Sold)))).ToList(); }
    public async Task<BookDetailDto?> GetBookAsync(int id) { var b = await Visible().Include(x => x.City).Include(x => x.Vouchers).ThenInclude(v => v.Provider).ThenInclude(p => p.Category).FirstOrDefaultAsync(x => x.Id == id); if (b == null) return null; var sold = await _db.PurchasedBooks.CountAsync(x => x.BookId == id && x.Status != PurchasedBookStatus.Refunded); var left = b.Vouchers.Count == 0 ? 0 : b.Vouchers.Min(v => Math.Max(0, v.ProviderQuota - sold)); return new BookDetailDto(b.Id, b.Title, b.Description, b.CoverUrl, new CityDto(b.City.Id, b.City.NameAr, b.City.NameEn), b.Price, b.Currency, b.ValidityDays, b.SaleStartAt, b.SaleEndAt, b.Vouchers.Sum(v => v.FaceValue * v.UsageLimit), left, b.Vouchers.OrderBy(v => v.DisplayOrder).Select(v => new VoucherDto(v.Id, v.Title, v.Description, v.DiscountType, v.DiscountValue, v.FaceValue, v.UsageLimit, v.Terms, new ProviderDto(v.Provider.Id, v.Provider.Name, v.Provider.LogoUrl, new CategoryDto(v.Provider.Category.Id, v.Provider.Category.NameAr, v.Provider.Category.NameEn, v.Provider.Category.Icon)))).ToList()); }
}
